mapper.select:
SELECT 
FROM dms_shop_product
WHERE id = #{id} AND tenant_id = #{tenantId}

SELECT FROM dms_shop_product WHERE tenant_id=#{tenantId} AND status=1 AND normal_sale_enabled=1 AND ( (
COALESCE(first_publish_time, create_time) >= #{cutoff} first_publish_time IS NOT NULL
) OR ( manual_new_arrival_enabled=1 AND (manual_new_arrival_end_time IS NULL OR manual_new_arrival_end_time > CURRENT_TIMESTAMP) ) ) AND (merchant_id IS NULL OR EXISTS ( SELECT 1 FROM dms_merchant active_merchant WHERE active_merchant.id=dms_shop_product.merchant_id AND active_merchant.tenant_id=dms_shop_product.tenant_id AND active_merchant.status=1 )) ORDER BY CASE WHEN manual_new_arrival_enabled=1 AND (manual_new_arrival_end_time IS NULL OR manual_new_arrival_end_time > CURRENT_TIMESTAMP) THEN 1 ELSE 0 END DESC, COALESCE(manual_new_arrival_start_time, first_publish_time, create_time) DESC, sort_order DESC, id DESC LIMIT #{limit}

SELECT FROM dms_shop_product
AND tenant_id = #{tenantId}
AND status = #{status}
AND merchant_id = #{merchantId}
AND category_name = #{categoryName}
AND ( product_name LIKE CONCAT('%', #{keyword}, '%') OR subtitle LIKE CONCAT('%', #{keyword}, '%') OR product_no LIKE CONCAT('%', #{keyword}, '%') )
AND (stock <= 0 OR EXISTS ( SELECT 1 FROM dms_shop_sku sku WHERE sku.product_id = dms_shop_product.id AND sku.status = 1 AND sku.stock <= 0 ))
AND ((stock > 0 AND stock <= safety_stock) OR EXISTS ( SELECT 1 FROM dms_shop_sku sku WHERE sku.product_id = dms_shop_product.id AND sku.status = 1 AND sku.stock > 0 AND sku.stock <= COALESCE(NULLIF(sku.safety_stock, 0), dms_shop_product.safety_stock) ))
AND stock > safety_stock AND NOT EXISTS ( SELECT 1 FROM dms_shop_sku sku WHERE sku.product_id = dms_shop_product.id AND sku.status = 1 AND sku.stock <= COALESCE(NULLIF(sku.safety_stock, 0), dms_shop_product.safety_stock) )
ORDER BY status DESC, sort_order DESC, id DESC

SELECT DISTINCT category_name FROM dms_shop_product WHERE status = 1 AND normal_sale_enabled = 1 AND (merchant_id IS NULL OR EXISTS (SELECT 1 FROM dms_merchant active_merchant WHERE active_merchant.id=dms_shop_product.merchant_id AND active_merchant.tenant_id=dms_shop_product.tenant_id AND active_merchant.status=1))
AND tenant_id = #{tenantId}
AND category_name IS NOT NULL AND category_name != '' ORDER BY category_name ASC

