UPDATE dms_shop_product
SET stock = stock - #{quantity},
    sales_count = sales_count + #{quantity},
    update_time = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND tenant_id = #{tenantId}
  AND status = 1
  AND (merchant_id IS NULL OR EXISTS (SELECT 1 FROM dms_merchant active_merchant WHERE active_merchant.id=dms_shop_product.merchant_id AND active_merchant.tenant_id=dms_shop_product.tenant_id AND active_merchant.status=1))
  AND stock >= #{quantity}

UPDATE dms_shop_product
SET stock = stock - #{quantity}, update_time = CURRENT_TIMESTAMP
WHERE id = #{id} AND tenant_id = #{tenantId} AND stock >= #{quantity}
